var value = pen.text
if (value > 0) {
    pen.animateReverse = false
}
if (value < 0) {
    pen.animateReverse = true
}

var value = pen.text
var id = pen.id
if (value == 1) {
    meta2d.setValue({ id: id, showChild: 0 }, { render: false, doEvent: false, history: false })
} else {
    meta2d.setValue({ id: id, showChild: 1 }, { render: false, doEvent: false, history: false })
}

